void ADukeHUD::Text(const FString& S, float X, float Y, const FLinearColor& C, UFont* F, float Scale, bool bCenter, bool bRight)
{
	if (S.IsEmpty()) return;
	float W = 0.f, H = 0.f;
	GetTextSize(S, W, H, F, Scale);
	if (bCenter) X -= W * 0.5f;
	if (bRight) X -= W;
	DrawText(S, FLinearColor(0.f, 0.f, 0.f, C.A * 0.85f), X + 2.f, Y + 2.f, F, Scale);
	DrawText(S, C, X, Y, F, Scale);
}

void ADukeHUD::Minimap(float X, float Y, float Size)
{
	ADukeGameMode* GM = ADukeGameMode::Get(this);
	UDukeGameInstance* GI = GM ? GM->Data() : nullptr;
	APawn* P = UGameplayStatics::GetPlayerPawn(this, 0);
	APlayerController* PC = GetOwningPlayerController();
	if (!GI || !P || !PC) return;
	DrawRect(FLinearColor(0.02f, 0.03f, 0.04f, 0.75f), X, Y, Size, Size);
	const float Range = 22000.f; // cm shown across the map
	const float K = Size / Range;
	const FVector C = P->GetActorLocation();
	const float Yaw = FMath::DegreesToRadians(PC->GetControlRotation().Yaw);
	const float Cs = FMath::Cos(Yaw), Sn = FMath::Sin(Yaw);
	const FVector2D Mid(X + Size * 0.5f, Y + Size * 0.5f);
	auto ToMap = [&](const FVector& W)
	{
		const float Dx = W.X - C.X, Dy = W.Y - C.Y;
		const float Fwd = Dx * Cs + Dy * Sn, Rt = -Dx * Sn + Dy * Cs; // camera-relative
		return FVector2D(Mid.X + Rt * K, Mid.Y - Fwd * K);
	};
	auto Inside = [&](const FVector2D& Q) { return Q.X > X && Q.Y > Y && Q.X < X + Size && Q.Y < Y + Size; };
	const float B = GI->BlockSize * 100.f;
	const int32 N = GI->GridN;
	for (int32 i = 0; i <= N; ++i)
	{
		for (int32 Axis = 0; Axis < 2; ++Axis)
		{
			const int32 Steps = 24;
			FVector2D Prev;
			for (int32 s = 0; s <= Steps; ++s)
			{
				const float T = (float)s / Steps * N * B;
				const FVector W = Axis == 0 ? FVector(i * B, T, 0.f) : FVector(T, i * B, 0.f);
				const FVector2D Q = ToMap(W);
				if (s > 0 && Inside(Q) && Inside(Prev)) DrawLine(Prev.X, Prev.Y, Q.X, Q.Y, FLinearColor(0.55f, 0.57f, 0.6f, 0.9f), 3.f);
				Prev = Q;
			}
		}
	}
	if (GM->bHasObjectiveLocation)
	{
		FVector2D Q = ToMap(GM->ObjectiveLocation);
		Q.X = FMath::Clamp(Q.X, X + 6.f, X + Size - 6.f); Q.Y = FMath::Clamp(Q.Y, Y + 6.f, Y + Size - 6.f);
		DrawRect(FLinearColor(1.f, 0.72f, 0.1f), Q.X - 5.f, Q.Y - 5.f, 10.f, 10.f);
	}
	for (ADukeVehicle* V : GM->Vehicles)
		if (V && V->bPolice && V->bChase)
		{
			const FVector2D Q = ToMap(V->GetActorLocation());
			if (Inside(Q)) DrawRect(FMath::Frac(GetWorld()->GetTimeSeconds() * 2.f) < 0.5f ? FLinearColor::Red : FLinearColor::Blue, Q.X - 3.f, Q.Y - 3.f, 6.f, 6.f);
		}
	DrawRect(FLinearColor::White, Mid.X - 4.f, Mid.Y - 4.f, 8.f, 8.f);
}

void ADukeHUD::DrawHUD()
{
	Super::DrawHUD();
	ADukeGameMode* GM = ADukeGameMode::Get(this);
	UDukeGameInstance* GI = GM ? GM->Data() : nullptr;
	if (!GM || !Canvas) return;
	const float W = Canvas->ClipX, H = Canvas->ClipY, S = FMath::Clamp(H / 1080.f, 0.6f, 2.f);
	UFont* Big = GEngine->GetLargeFont();
	UFont* Med = GEngine->GetMediumFont();
	UFont* Small = GEngine->GetSmallFont();
	const float Now = GetWorld()->GetTimeSeconds();
	ADukePlayerController* PC = Cast<ADukePlayerController>(GetOwningPlayerController());

	if (GM->bTitleCard && GI)
	{
		DrawRect(FLinearColor(0.f, 0.f, 0.f, 0.72f), 0.f, 0.f, W, H);
		Text(GI->MenuTitle.ToUpper(), W * 0.5f, H * 0.36f, FLinearColor(1.f, 0.78f, 0.25f), Big, 3.2f * S, true);
		Text(GI->CityName, W * 0.5f, H * 0.36f + 90.f * S, FLinearColor::White, Med, 1.4f * S, true);
		Text(TEXT("Press Enter to start"), W * 0.5f, H * 0.7f, FLinearColor(1, 1, 1, 0.8f), Med, 1.f * S, true);
		return;
	}
	if (PC && PC->bMenu)
	{
		DrawRect(FLinearColor(0.f, 0.f, 0.f, 0.6f), 0.f, 0.f, W, H);
		Text(TEXT("PAUSED"), W * 0.5f, H * 0.4f, FLinearColor::White, Big, 2.5f * S, true);
		Text(TEXT("Enter: resume     Q: quit to desktop"), W * 0.5f, H * 0.4f + 80.f * S, FLinearColor(1, 1, 1, 0.85f), Med, 1.f * S, true);
		return;
	}
	if (!GI) return;
	// top right: cash, clock, wanted
	float Y = 24.f * S;
	if (GI->bCashHud) { Text(FString::Printf(TEXT("$%d"), GM->Cash), W - 30.f * S, Y, FLinearColor(0.45f, 0.9f, 0.5f), Big, 1.6f * S, false, true); Y += 52.f * S; }
	const int32 Hh = FMath::FloorToInt(GM->GameHour), Mm = FMath::FloorToInt(FMath::Frac(GM->GameHour) * 60.f);
	Text(FString::Printf(TEXT("%02d:%02d"), Hh, Mm), W - 30.f * S, Y, FLinearColor::White, Med, 1.2f * S, false, true); Y += 36.f * S;
	if (GI->bWantedHud && GI->bWanted)
	{
		FString Stars;
		for (int32 i = 0; i < GI->MaxWanted; ++i) Stars += i < GM->GetWanted() ? TEXT("*") : TEXT(".");
		Text(Stars, W - 30.f * S, Y, GM->GetWanted() > 0 ? FLinearColor(1.f, 0.85f, 0.2f) : FLinearColor(1, 1, 1, 0.35f), Big, 1.5f * S, false, true);
	}
	// objective
	Text(GM->Objective, W * 0.5f, 24.f * S, FLinearColor(1.f, 0.85f, 0.45f), Med, 1.1f * S, true);
	// minimap, district, health
	const float MapSize = 230.f * S, MX = 28.f * S, MY = H - MapSize - 60.f * S;
	if (GI->bMinimap) Minimap(MX, MY, MapSize);
	APawn* Pawn = UGameplayStatics::GetPlayerPawn(this, 0);
	if (Pawn) Text(GI->DistrictNameAt(Pawn->GetActorLocation()), MX + MapSize + 22.f * S, H - 100.f * S, FLinearColor::White, Big, 1.2f * S);
	if (ADukeCharacter* Hero = GM->PlayerChar)
	{
		const float HP = FMath::Clamp(Hero->Health / Hero->MaxHealth, 0.f, 1.f);
		DrawRect(FLinearColor(0, 0, 0, 0.6f), MX, H - 48.f * S, MapSize, 12.f * S);
		DrawRect(FLinearColor(0.3f, 0.85f, 0.35f), MX, H - 48.f * S, MapSize * HP, 12.f * S);
		if (Hero->Armor > 0.f) DrawRect(FLinearColor(0.35f, 0.6f, 1.f), MX, H - 32.f * S, MapSize * FMath::Clamp(Hero->Armor / 100.f, 0.f, 1.f), 8.f * S);
		// weapon / ammo
		if (Hero->Slot >= 0 && GI->Weapons.IsValidIndex(Hero->Owned[Hero->Slot]) && !Cast<ADukeVehicle>(Pawn))
		{
			const FDukeWeaponDef& Wd = GI->Weapons[Hero->Owned[Hero->Slot]];
			Text(Wd.Name, W - 30.f * S, H - 110.f * S, FLinearColor::White, Med, 1.1f * S, false, true);
			Text(FString::Printf(TEXT("%d / %d"), Hero->Clip[Hero->Slot], Hero->Reserve[Hero->Slot]), W - 30.f * S, H - 76.f * S, FLinearColor::White, Big, 1.3f * S, false, true);
			// crosshair
			const FLinearColor CC = Now - Hero->HitMarkerTime < 0.2f ? FLinearColor::Red : FLinearColor(1, 1, 1, 0.85f);
			const float G = Hero->bAiming ? 4.f : 9.f;
			DrawLine(W * 0.5f - G - 8.f, H * 0.5f, W * 0.5f - G, H * 0.5f, CC, 2.f);
			DrawLine(W * 0.5f + G, H * 0.5f, W * 0.5f + G + 8.f, H * 0.5f, CC, 2.f);
			DrawLine(W * 0.5f, H * 0.5f - G - 8.f, W * 0.5f, H * 0.5f - G, CC, 2.f);
			DrawLine(W * 0.5f, H * 0.5f + G, W * 0.5f, H * 0.5f + G + 8.f, CC, 2.f);
		}
	}
	if (ADukeVehicle* V = Cast<ADukeVehicle>(Pawn))
	{
		Text(FString::Printf(TEXT("%d km/h"), FMath::RoundToInt(V->SpeedKmh())), W - 30.f * S, H - 80.f * S, FLinearColor::White, Big, 1.8f * S, false, true);
		if (!V->DisplayName.IsEmpty()) Text(V->DisplayName, W - 30.f * S, H - 120.f * S, FLinearColor(1, 1, 1, 0.8f), Med, 1.f * S, false, true);
	}
	// name tags
	if (Pawn)
		for (ADukeCharacter* C : GM->People)
		{
			if (!C || C->bDead || C->DisplayName.IsEmpty()) continue;
			const float D = FVector::Dist(C->GetActorLocation(), Pawn->GetActorLocation());
			if (D > 2500.f) continue;
			const FVector P = Project(C->GetActorLocation() + FVector(0, 0, 120.f));
			if (P.Z <= 0.f) continue;
			Text(C->DisplayName, P.X, P.Y, FLinearColor(1.f, 0.85f, 0.4f, FMath::Clamp(1.f - D / 2500.f, 0.3f, 1.f)), Small, 1.2f * S, true);
		}
	// prompt, subtitles, big messages
	Text(GM->Prompt, W * 0.5f, H * 0.78f, FLinearColor::White, Med, 1.1f * S, true);
	if (GI->bSubtitles && Now < GM->SubtitleUntil)
	{
		const FString Line = GM->SubtitleSpeaker.IsEmpty() ? GM->SubtitleText : GM->SubtitleSpeaker + TEXT(": ") + GM->SubtitleText;
		Text(Line, W * 0.5f, H * 0.86f, FLinearColor::White, Med, 1.15f * S, true);
	}
	if (Now < GM->BigTextUntil)
	{
		Text(GM->BigText, W * 0.5f, H * 0.32f, FLinearColor(1.f, 0.75f, 0.2f), Big, 2.6f * S, true);
		Text(GM->SmallText, W * 0.5f, H * 0.32f + 80.f * S, FLinearColor::White, Med, 1.3f * S, true);
	}
}
